import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"紫岩易传卷二","description":"紫岩易传 - 紫岩易传卷二","frontmatter":{"title":"紫岩易传卷二","description":"紫岩易传 - 紫岩易传卷二"},"headers":[],"relativePath":"zh/classics/ziyan/003.md","filePath":"zh/classics/ziyan/003.md"}'),r={name:"zh/classics/ziyan/003.md"};function i(n,p,c,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="紫岩易传卷二" tabindex="-1">紫岩易传卷二 <a class="header-anchor" href="#紫岩易传卷二" aria-label="Permalink to “紫岩易传卷二”">​</a></h1><p>钦定四库全书</p><p>宋张浚撰</p><p>䷊ 乾下坤上 泰：小往大来，吉亨。彖</p><p>曰：「泰，小往大来，吉，亨」。则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人。君子道长，小人道消也。坤变而乾，阴往于外，阳来于内，阴小阳大，君子、小人之分也。「大来」何以为「泰」？「大来」则自君及天下无不正，至格天地，裕万物，安中国，服四夷，宜其泰。然则人君盍为而能致大者之来，其必自心始。人君之心刚于内，则君子之有刚德者并进。夫君之心若曰：「我之社稷将有以保之，我之百姓将有以利之。」吾心勃然改不善而从其为善。正念一兴，天地鬼神知之，君子闻风，孰不改图而来乎？使君而无有是念，是阳气未复，天未欲泰也。君子知夫道之不同，不肯违天以幸万一，得以危其身，以败乱天下国家。阳自内来，一为复，二为临，三为泰。至泰，刚德成矣。刚内为泰，其心刚也。于是刚德之君子悉处于内，为心腹。在要职者，莫非君子，罔有小人间之。夫为人君而刚内柔外，执德之中，皇极之道斯为尽。是必寡欲而无私，必以社稷天下为己忧，必能断而不惑于众说，小人将何所容迹哉？往来自此判然，则言致「泰」者，在君心之刚而已。「泰」治功利及天地万物，曰「吉亨」。「泰，小往大来，吉亨」，则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人。君子道长，小人道消也。申言「泰」之所以为「泰」也。君子类进，发号施令，罔有不顺人心者。人心悦归，和气可致，故天地交而万物通。方春三阳用事，天地之气腾降于上下，而万物莫不奋达，交通之应也。而天地之气得其正，实自夫君子𫉬用于时。何谓「上下交而其志同」？君臣之志，在天下而不在身，是为「志同」。「上下交」云者，君之心即臣心，臣之心即君心，相与以诚，谗邪莫闲，是为「交」。二事皆国有君子致之，故曰：则是天地交而万物通也，上下交而其志同也。内阳外阴，阴阳得正也；内健外顺，君臣得体也。君用健，臣用顺，事无不济。「内君子而外小人」，君子小人各当其位也。圣人之于小人也，外而已。如曰必绝弃之，则奸心滋生，为吾治害，外之所以俟其化，圣人之心仁矣，大矣夫！象曰：天地交，「泰」。后以财成天地之道，辅相天地之宜，以左右民。</p><p>君子并进，治道可行。正心术而五行得其序，敷政教而万物得其性，自然民协于中。致力于天地，是致力于民也。夫财成本自君心，心正则身正，身正则所为罔不正，固有以格天地而均节其道，其用微矣。若夫辅相，则见于政教之迹，因天下万物之宜，而还以导之也。箕子为武王陈洪范，自五行至五福六极，财成辅相之道毕备其中。其曰：「敛时五福，用敷锡厥庶民。」凡厥庶民，惟汝极，锡汝保极，所以左右民者至矣。坤众在外为民，且阳下阴上，二气交感，各得其中。阳为左，阴为右，左右之而使归中也。</p><p>初九，拔茅茹，以其汇，征吉。象曰：拔茅征吉，志在外也。何取于茅？以况君子有洁白正直之德，而可以通神明也。君子不后时以缩，在泰必类而进，为道为天下也。曰「志在外」，且上有柔中之君，下有同志之贤，进必合，合必泽加于人，曰「征吉」。乾初变巽为「茅」，三阳连进为「拔茅」，为「汇」。初应四而二刚俱上应，曰「以其汇征」。</p><p>九二，包荒，用冯河，不遐遗，朋亡，得尚于中行。象曰：「包荒」，「得尚于中行」，以光大也。</p><p>二有乾刚之德，其容如天，其公如天，中道上通，君心应之。「包荒，用冯河」，容也；「不遐遗，朋亡」，公也。「包荒」则不才者勉，「冯河」用则强暴者化。「不遐遗，朋亡」，则志仁身正，臣道洪矣。泰治之时，君臣各得其志，为大臣者，孰不以天下为心，且以天下为公哉？二刚中，知保治之难，汲汲乎荒之包、「冯河」之用，不以远弃，不以近比，所以作成人才，杜绝私党之意甚备，宜得尚于中行之君也。尝考二之心，处至治而兢兢若未治，惟恐一夫失所，一才见弃，一事不公，有以害吾治，其为中也至矣，事业岂不从而光大哉？坤阴在上，「包荒」象。三比众阴，二承之，用「冯河」象。阴荒也，阴在外，「包」也。阳刚不中，「冯河」也。应坤为「不遐遗」，为「朋亡」。乾中为光大。九三，无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。象曰：「无往不复」，天地际也。</p><p>天地气数中则平，过中必变，人事亦然。圣人知几，示训于泰，观山川陵谷之迁变，日月星辰之推移，平陂往复，故不能逃气数自然也。夫治至于「泰」，其君必骄，其臣必怠，其德必衰，其政必慢，斯亦自然之理。不有刚德君子，知艰守正，不恤一己利害，而尽诚以辅道其君，俾知夫以泰为忧，不以为乐，鲜不颠覆于后也。九三虽刚过不中，而有乾健震动不息之体，故勉以孚若曰：「尽在我之诚，以启迪弼正，而不恤其他，则泰治可长保也。」夫国家尊荣，君子食人之禄，可以无愧，而道行志得，利泽加施矣。曰「于食有福」，乾坤相交而中，进退盈虚自此分，平陂往复所由生也。互兑，兑口为食，阳为福。互体震，震以恐致福。</p><p>六四，翩翩，不富以其邻，不戒以孚。象曰：「翩翩」「不富」，皆失实也。「不戒以孚」，中心愿也。三阳内升，君子盛矣。其道足以格小人而信之，俾率类从化。君子为天下图，何其远乎！夫小人未尝一日无于世，使之中心乐从君子之化，是小人皆为君子也。泰至是而盛。四自内为三阴首，下从群阳，其顺若鸟飞有翩翩势，小人降心从君子象也。知君子有可信之道，其心若一，「不戒以孚」，安有害治于后者哉？阴下顺为「翩翩」，阴虚为「不富」，三阴为「邻」，阴从阳为「孚」，反兑为「不戒」。六五，帝乙归妹，以祉元吉。象曰：「以祉元吉」，中以行愿也。帝乙，古贤王称也。在易象取谦以下下之义。甲十日长，乙次也。舍甲之刚，用乙之柔，非贤德之君，孰能为之？归妹谓何？应九二而并与三阳下之也。三阳而谓之「妹」，三阳自坤变，有「妹」象也。「祉」谓何？福也。治盛而天降之休曰「祉」。六五为泰主，以柔用中，不谓既治而一日忘下贤，广览博取，惟恐英才一或沉于下，其于天下之仁有加无已，于此见其心矣。呜呼！贤者民之命，天下赖以生也。至治而不忘下贤，英才继进，如妹之归，生化之功此为大。曰「以祉元吉」，云以仁而𫉬吉之大也。</p><p>上六，城复于隍，勿用师，自邑告命，贞吝。象曰：「城复于隍」，其命乱也。</p><p>在泰以阴居上，刚德不足，而权移于下，众失于内，否其反矣。「城复」，失众也。失众何以守邦，况用师乎？「勿用师」云者，当反己而自治耳。「自邑告命」，命自下出也。命不由君，其吝为贞。且天下之乱，莫大于权臣擅命，而政出多门，读雨无正之诗可以槩见，此最泰极之大戒。嗟夫！治至泰极，荒淫骄奢所自生也。荒淫骄奢之主，命必移于臣，而天下之心失矣。内何以守，外何以战哉？坤土为城。复互兑互巽为告命。䷋ 坤下乾上</p><p>否之匪人，不利君子贞，大往小来。彖</p><p>曰：「否之匪人，不利君子贞，大往小来」，则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。否三阴在内，其象有二：人君刚德消于内，一象也；小人柔邪者毕处要位而擅事于内，二象也。盖人君刚德既消，则小人乘闲缘类而进，莫可止遏矣。孰为人君之刚，远声色，轻货利，舍一己之乐，先百姓之忧，君之刚也。「否」，将有蔑贞之凶，君子卷道而怀可也，故「不利君子贞」。君子不用，国非国矣。天地不交，是阴阳错乱，万物不得遂其生也。上下不交，是君臣各有心，其道不通。为君者骄亢于上，为臣者蔽塞于下，纲纪法度，荡然不复有也。此犹可以为国乎？否、泰，内外卦体同也。泰曰：「健顺至否，易之为柔刚。」盖君臣失德，已见于事。朝廷微弱，诸臣强大，中国微弱，四夷强大，内柔外刚，义也。嗟乎！君子一不用于时，大而天地，细而万物，俱不得其理。且君臣各有心，志不在天下，曰有邦与无邦同。夫君子为国轻重如此，而世主贪一己私欲，疏远刚贤，终莫悟也。嗟乎！坤内，邦邑象也。「否」以「乾」变，「乾」，君道也，而「坤」阴变其内，刚德消矣。夫人君内无刚德，则政失厥中，小人乘隙以进，而祸乱亟作，「否」所由成也。且致「否」者，人也，而「否」之则匪人。不然，何以弃君子不用，自罹其祸？夫用君子必治，用小人必乱，此亘古今不易之理。今也舍君子而用小人，其必以小人为君子矣。兹非天夺之鉴而然乎？圣人知其不可奈何，而曰「否之匪人」，慨叹之辞也。变「坤」为「泰」，变「乾」为「否」，阴可消也，阳不可消也。「坤」变至三，君之刚德沦丧殆尽。是以「否」一阴生曰「姤」，二曰「遁」，三曰「否」，至「否」，刚德内消矣。小人得志，引类而来，亦声同气感之符也。尝考唐明皇在开元时，侈心已萌于中，若「姤」一阴之始生，云杨、李乘闲进，卒肇大乱。人君慎夫心念之微哉！</p><p>象曰：天地不交，「否」。君子以俭德辟难，不可荣以禄。君子共俭律身，不为时变。「否」之「俭德」，盖隐德不彰，可言不敢言，可为不敢为，高爵厚禄，可致不敢致。君子非忘君，且忘天下也。知夫言为之无益，祗害其身，而正道一丧，将孰与维持振起之于后？君子见几，其心仁。「坤」吝啬为俭德，三阳在外为「辟难」，阳本内也，而居外为不可荣。「坤」邑为「禄」。</p><p>初六，拔茅茹，以其汇，贞吉，亨。象曰：「拔茅」「贞吉」，志在君也。相期以守正，是为忧君之深。君子阳阳，诗相招为禄仕，全身远害而已。盖君子为正之守，所以存道，道存而志可行。且国有人焉，国终不亡矣，兹亦不忧君者所为与？曰「志在君」，否三阴在内，小人用事时也。而初「贞吉」，二「否亨」，皆君子事，何邪？曰：圣人不与小人在内，勉君子使各尽其道也。圣人仁爱生民，不忍小人迭进以害其生，其意不亦远哉？「茅」，至柔物，乾一变巽为「茅」，三阴为「汇」，初本乾体为「贞」。「茹」，根也。初应四，连四之刚，与阳俱退，贞可嘉也。</p><p>六二，包承，小人吉，大人否，亨。象曰：「大人否，亨」，不乱群也。包初承三，俟时之复，其事则「吉」，其道以「亨」。陈卑用于汉，狄仁杰用于唐，二得中于「否」，曰「大人」。大人以道为任而识其大者，不肯规规然自异群阴中，招怨取疑以害吾道也。曰「不乱群」，「否」之二五何以皆曰「大人否」？阳消阴盛卦也，非智识洪大者为之扶危解纷，天下终否而已。二五得刚柔中，圣人立此象勉后世君臣，使不以既否而怠其道。且君子俱退己独进为体道之权，不失其正，此又二所以为大而亨于否也。</p><p>六三，包羞。象曰：「包羞」，位不当也。三过中有互「巽」兑体，于「否」为柔顺不正，且志在谀说者也。群阴用事，三先之，迹其不中不正之资，欺天罔上，妒贤贼民，何所不至？三顺而处之，不自以为羞，曰「包羞」。而仰视天，俯察地，终不能无歉于心也。阳在外为包巽进退不果为「包羞」。</p><p>九四，有命无咎，畴离祉。象曰：「有命无咎」，志行也。</p><p>君奉天命以施令，臣奉君命以行事，万世不易之理。而否乱之时，以刚德处近君位，能承君命而大有为于天下，臣之恭也，其事为难。四居互「巽」中，「巽」风为命，有刚德而巽顺事上，故能承命以动，均福其类。夫天下所同戴者，君也。近臣而挟刚以擅君命于「否」，是为权臣。夫权臣，天人之心所共恶而深疾之者，其背道失心，必遗害于天下后世，何祉之离？惟夫在「否」而以君命行志，于道为顺，且君子同心，致时于治，并受福矣。周公大诰、书命皆本成王，是以十夫翼予，大难竟平，曰「有命」，心每有之，不敢忽也。其至诚恭顺之意，未尝自用而忘君云。三阳为畴，阳实为「祉」。</p><p>九五：休否，大人吉。其亡其亡，系于苞桑。象曰：「大人」之吉，位正当也。</p><p>虑患若系马于苞桑者然。「苞桑」，民柔象也。有国之本在民，宁忍伤之？伤之则危亡无日矣。书曰：「若朽索之御六马。」为人上者，奈何不敬？系桑之义也。且休否之道，在于安，在于存，在于治，不待夫既否而后为也。先事预图，此大人之所以吉与？九五以刚中至德，履乾位，下六二之贤而应之，君臣兢兢，思所以保乂百姓于上，无须臾忽其否可休，必致理也。且大人休否之功微矣，天下徒见其常安常存常治，而莫知所以休之道。诗曰：「迨天之未阴雨，彻彼桑土，绸缪牖户。」孔子曰：「为此诗者，其知道乎？」「休否」，非知道者莫能也。互体巽，巽柔木，为苞桑。巽绳直为系。乾五为大人。呜呼！民者，国之元气也。人君一念在民，则恣情悖理之事，必不肯更为。民之心归之，元气复矣，否以休也。人君惟患乎不能诚意以复其心，心复而天人可格，为用岂不大哉？其亡其亡，又以见其心念之正也。</p><p>上九：倾否，先否后喜。象曰：否终则倾，何可长也。</p><p>天地之理，阴阳之运，数极必反。上九居否终，以乾刚之德在上，进德不已，阳可复而秦也，曰「先否从喜」。且数之消长，与德终始。人君尝因否极至时，固有可倾之道，苟非自强其刚德，而以利天下、定社稷为志，优游玩日，则怠乐是安，否不可得而倾矣。为君者，其勉于刚不可归之时，而曰姑俟时之来也，必若上九之刚，而后否可倾，可不戒夫！互兑为「后喜」。䷌ 离下乾上</p><p>同人于野，亨。利涉大川，利君子贞。彖</p><p>曰：同人，柔得位得中而应乎乾，曰「同人」。同人曰</p><p>「同人于野，亨」。「利涉大川」，乾行也。文明以健，中正而应，君子正也。惟君子为能通天下之志。</p><p>君子至明之德，上同于天，故能同天下，而天下心归之，曰「同人」。大同无私，若天之公，曰「于野亨」，野旷大，无适莫之地，公道盛行，大难以济，曰「利涉大川，利君子贞」。不正则有所不利。君子秉文明中正之德，天下所谓善与同好，天下所谓恶与同恶，欲与聚，恶勿施，天下之心孰不服从？是为同人之「贞」。乾上为野。乾健为「利涉大川」。九五刚中，为君子，为贞。柔得位、得中而应乎乾，曰「同人」。</p><p>「同人于野，亨，利涉大川」，乾行也。文明以健，中正而应，君子正也。惟君子为能通天下之志。申言同人之所以为同人也。六二以柔中为一卦主，而上应九五，曰「柔得位、得中而应乎乾」。九五德同于天，故不曰「刚」而曰「乾」。夫以大中应乾，而群阳毕从，则所同者大。乾行，谓其道不息，难以健济。文明，离体。健，乾体。以礼交物，物无不烛，曰「文明」。文明而用以诚之谓「健」。「中正而应」，谓五。五以大中至正之道，下应于二，曰「中正而应」。二、五应，天下莫不应，君子之贞，不亦大哉！夫贞，天下所归。惟贞则以我之心为天下心，欲恶靡不一，且将合天下之志通为一矣，曰「惟君子为能通天下之志」。离火在人属心为志。</p><p>象曰：天与火，同人。君子以类族辨物，</p><p>不同同之，非有至公至明之德，何以克为？自伏牺至周，人各有族类而辨之，则愚智处宜，贵贱履位，贤不肖袭情。记曰：「非此族也，不在祀典。」然则君子小人善恶，凡以类同者，皆曰「族类」，而用辨大同之道也。族类物辨，天下以治，则车书可同，四海可一矣。火性炎上，与天同体，同人取天火立象，君子法象，则法其至公至明之德而已。</p><p>初九，同人于门，无咎。象曰：出门同人，又谁咎也！</p><p>出而不忤于物，故得物之情而可以用其同。自为崖异怪激之行，谁其从之？不若静退不出之愈也。初履刚，有离明德，位居同人先，而泛然能与人同，无私党偏系心，是必将揽天下之情而用其同于后，故无咎。盖君子之同，非物我尽忘，浑浑与世为一，如庄老所为也。彼将有以用其同于天下，使天下各蒙其惠利，不苟然耳。二以阴在上为门。</p><p>六二，同人于宗，吝。象曰：「同人于宗」，吝道也。</p><p>二柔中为一卦主，圣人严为之训曰：「同人于宗，吝」。夫君子无意于天下则已，君子而有意惠利天下，非同人则莫为之助，而所同之狭，亦不能大有为于时。且二以阴居五阳中，群阳乐同，傥必欲舍刚阳，惟柔阴之从，则为我应者鲜矣，又安能广揽人才，以辅成人主有大之业哉？宜其「吝」。象释之曰「吝道」，谓于道为吝也。或曰：应五为宗。夫二五君臣位，且五阳二阴，非己宗也。语曰：「如有周公之才之美，使骄且吝，其余不足观也已。」周公惟贤才并用，不牵私党，道以盛行，二其慎哉！二居离中，离丽必有所附，其在同人，不可不慎。</p><p>九三，伏戎于莽，升其高陵，三岁不兴。象曰：「伏戎于莽」，敌刚也。「三岁不兴」，安行也。</p><p>离处乾下，「离」为戈兵，为伏戎。互体巽兑，巽以阴木生兑泽为莽。变乾有重艮体，为高陵。「三岁」，乾数。夫二五正应，三四以刚闲之，譬诸侯强大，与夫小人才健，害吾君臣正应，惧圣贤同心而正道行于天下，己不得以逞肆私欲，非己之利者，大可畏哉！夫小人为身计，不为国计，不为百姓计，设心不仁，莫肯恤也。三岁不兴，而象曰「安行」，盖以恶长不悛，恬不知悔。吁！其可畏也夫！</p><p>九四：乘其墉，弗克攻，吉。象曰：「乘其墉」，义弗克也。其吉则困而反则也。</p><p>四位近君而以阳居阴，知道之不胜，而能自反以归义，故吉。吾于此见圣人之心许迁善，困而反则谓不害其为同也。九四乘离之刚，离中虚，阳包之为墉。夫二五以中直相与，天人与之义安可闲？义所弗克而反身从义，弃前非，图后善，是不拂于天地之心矣。</p><p>九五：</p><p>同人，先号啕而后笑，大师克相遇。象曰：同人之先，以中直也。大师相遇，言相克也。心通迹闲，其忧在先。道之苟胜，闲何能为？吁！经天地，理万物，莫大乎中直。夫中直，物可格也，况于人乎？中直则君臣之心本自相通，何忧不遇？同人本离体，而天之与火，其德又同，二五俱得中位，是五之心即二心，二之心即五心，其为中直也大矣。系辞曰：「二人同心，其利断金。」同心之言，其臭如兰。以离火乘乾金，其心无所不通，非强梗坚刚者所能闲，曰断金。心同而发号施令，罔不尽善，曰如兰。互巽为兰。夫五二正应，而二刚害之，二刚方健，己德不足，必欲以己不正之心求合于上，嫉媢有德，排之谗之。九五刚中，心惟二同，卒用相遇，以一天下而静，其难，可谓盛矣。「先号啕后笑」，何也？以天下为忧，至诚恻恒之意发见于外，曰「号啕」。君臣相遇，道行天下，有足乐者，曰「后笑」。忧乐在天下而不在身，圣贤之心也。互离巽兑，巽风兑说，兑口为号啕，为笑。大师克相遇。「克」，言与之者众，所胜在道，若师之克。离为戈兵，九五以刚处中，离体在下，群阳从之，为「大师」。呜呼！君臣之闲，亦在夫勉己中直之心而已。中直者，无欺愧于天地，为用至大。故惟中直，则君臣一心，而可以大同于天下也。</p><p>上九：同人于郊，无悔。象曰：「同人于郊」，志未得也。</p><p>邑外为郊，远人而同之于郊，相与为澹泊寂寞之游，忘宠辱，远势利，悔无自生。虽然，君子之心未尝一日不在天下，使得位于时，今日设施，前日静养功耳。「同人于郊」，志虽未得，悔则无之，其心初不忘天下也。乾上为「郊」，邑内也，郊外也。且郊犹取于「同人」，君子何适不用其同邪？虽穷居约处，而志同道合，以琢以磨，君子进德，不谓居无事而辄已也。䷍ 乾下离上 「大有」，元亨。彖</p><p>曰：「大有」，柔得尊位，大中而上下应之，曰「大有」。其德刚健而文明，应乎天而时行，是以「元亨」。</p><p>「大有」自「乾」变，「乾」变而「巽」，仁德以行，所亨者大，曰「元亨」。六五盖「乾」五尊位，惟其以「乾」刚用离明，体协大中，上下群阳莫不毕应，曰「柔得尊位大中，而上下应之」。夫中者，天下之所归，而况于贤哉？刚贤毕应，所有者大，是为「大有」。「刚健文明」，二体刚健善断，文明善应。「刚健」而诚尽于内，文明而礼尽于外。合是二美，中德斯大其位得乾之中，曰「大中」。「应乎天而时行」，谓五求乾刚，稽诸天道，而用离柔离万物相见于时为正，为「时行」。「时行」云者，盖以当有大之世，非用柔无以得天下贤，非得贤无以保天下大业。「时乎时，不可违也。」人君仁德，至是大矣。</p><p>象曰：火在天上，「大有」，君子以遏恶扬善，顺天休命。如日之升，明德普施。明德既行，则善恶各得其正，而天休滋至矣。夫善者，天下所甚爱，恶者，天下所甚恶。善必善加于天下，恶必恶加于天下。遏恶扬善，以顺天下心，是为「顺天」。天人之心，本自一致也。天心眷佑，和气致福，休命之来，莫可止御，人君大业，其将永久不替。夫火有扬之之义，天有遏之之义。详观此象，而知善人之有益天下国家也。善人在上，天休滋至，然则曷可不亟求之于微下而进用之哉？卦自一变，「坤」至五而「艮」止之，四阳俱复，是为「大有」。阳善阴恶，为遏恶扬善。</p><p>初九：无交害，匪咎，艰则无咎。象曰：大有初九，「无交害」也。初居四阳下，曰「无交害」；四居四阳上，曰「匪其彭」。何义也？初未有位，当「大有」时，君子莫不欲进以行其道。道之不行，君子耻之，惧利泽不及于人也，故曰「无交害」。若夫四处近君位，苟非以中正绝类之道立人之朝，则嫌疑谗谤之兴，殆不可遏止。明哲君子欲全其道以利天下，有所不肯为也，故曰「匪其彭」。虽然，无交非初罪也。四方体公忠事上，有炎上之体，初不得交。曰「匪咎惟艰」，以守贞安顺义命，不妄求合，上必我知，咎不长矣。曰「艰则无咎」，三阳在前，其行也艰，艰斯无咎。圣人著此训，恶夫舍正应而他适也。九二，大车以载，有攸往，无咎。象曰：「大车以载」，积中不败也。</p><p>处乾阳中，乾，良马，其德健。变卦有坤体为大车。臣之积中非一日，事中积用能任天下之重，如大车载物，沛乎其有余裕，曰「大车以载，有攸往，无咎」。「中」者何？总言之德也。其目正也，公也，直也，诚也，恭钦也，仁也，善也。凡德之美者皆曰「中」。君子于中不可须臾忘，闭邪去伪，止私寡欲，积中之道也。积若水之积，其积厚，其负大舟必胜任矣。二得乾刚正中，刚故不息，是以能积。且在上有柔中，君屈己下之群贤并进，而己独得中，君子志可行，时也，何往不利哉！呜呼！中不积则败天下事，生民之命将无所托。后之为臣，于大有慎勿以既治而怠其中也。一日失中，天下被害，可不畏与，可不慎与？</p><p>九三，公用亨于天子，小人弗克。象曰：「公用亨于天子」，小人害也。以直道格君非心，而致君为尧舜之君，大人事业。五以柔居离中，五阳宗之，曰天子。九三刚健履位，位居互乾中，用能尽至公之道，曰公。公道盛行大治，可永为国家之利无穷，曰「公用亨于天子，小人弗克」。小人不能胜己之私，不可与言公也。三重刚立，互巽初，互兑下，兑说巽顺为小人。呜呼！小人以事君为容悦，无所不用其私，为民之贼，为政之患，为国之忧，是将壅蔽其君以毒乱天下者也。使若斯人而居上位，必为天下大害。有大之君，尤宜察诸。</p><p>九四，匪其彭，无咎。象曰：「匪其彭无咎」，明辨晳也。</p><p>尽忠于君，无下比三阳之嫌，非见几孰能之？四以刚德为三阳先，且其位近承柔中之君，傥挟群阳以事上，得无矫拂取疑之忧乎？四「匪其彭」，非绝弃贤才而远之也，心公道直，不牵其私，使人人得尽其道于上，是谓「匪其彭」，是谓「无咎」。不然，蔽贤取容，将得罪天下后世，咎之大者。四位在离明先，下履乾刚，明足以辩得失祸福之几，而刚能行之，曰「明辨晳」。三阳为「彭」。</p><p>六五，厥孚交如，威如，吉。象曰：「厥孚交如」，信以发志也。「威如」之吉，易而无备也。</p><p>君臣交孚以道，则德修政立，天下𫹷然迁善远罪而莫敢为非，虽荒服远裔，知所畏慕，率从吾化，初不待征伐刑罚之施也。六五自乾变，内刚外明，其明足以知天下之贤。九二刚中，顺而应之，刚柔相交，一德以孚，曰「厥孚交如，威如，吉」。离为火，为戈兵，为「威如」。夫圣人有天下大业，政令教化之防，不可一日弛，自古纪之。六五威如，象辞何取夫易而无备？传曰：「百万之众，不如一贤。」盖贤者立人之朝，则众贤从而辅之。君正于上，纲纪法度明于下，君臣相说，德威远扬，四方莫敢予侮。不必屑屑然事备具之末，非谓坏法乱纪，漠然无以备也。卦本乾体，乾以易知曰：易。尧舜之时，君臣惟道德是弘，民不犯有司，蛮夷率服，威如也。尧舜安用备？惟其君臣交孚，所备大矣。信以发志谓何？夫君臣而一有欺愧之心，必不能相与合志而有为。君臣之间，宜先勉夫信，信立而志发于外，斯有合矣。五柔中为无备。离明中虚为信，为志。</p><p>上九：自天祐之，吉无不利。象曰：大有上吉，「自天祐」也。上九以乾体位离明上，刚健有明德，故能上贤而「自天祐之」。夫子系辞释之曰：「履信思乎顺，又以尚贤也。」盖信顺可以得天，人心信顺一体，事顺天者，必信于人。上九体信顺在上，又能以此尚信顺之臣，君臣遇合，其道盛行，而惠泽加于天下，是以「自天祐之，吉无不利」。爻独曰「自天祐之」，辞兼天人而言。天无心，以人为心，人之所助，天其祐之也。昔夫子对子贡「足食足兵」问，谓兵食可去，民无信不立。盖号令赏罚举措之闲，一失其信，天下将漠然离心，莫可复合。虽有兵食，无补于用。是逆天者所为，何以得天下之贤，与之共保有大之治？上九躬履信顺，刚贤毕应，人既助之，天道斯祐，其吉大矣。互兑承之，为「履信」。乾五变得坤卦复于乾，「坤」伏其下，为「思乎顺」。䷎ 艮下坤上 「谦」，亨，君子有终。</p><p>彖曰：「谦，亨」。天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。「谦尊而光，卑而不可逾」，君子之终也。</p><p>自天子至庶人，未有不谦而能保国持身。谦则虚，虚则久，久则光大之道也。惟有德者为能「谦」。卦体内止外顺，德盛而止于内，礼恭而顺乎外，是为「谦」。无德而徒为卑顺焉，礼之文也。君子用止于谦，凡外物之役吾心意，与夫穷通得丧之分，好恶喜怒之节，饮食言语之宜，处之不竞，守以至虚，节以礼义，持以退抑，天道所喜，神物所祐，民人所归，其为亨也大矣。艮在下，「艮」，万物终始为有终。天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。何谓也？天地人一道，幽明一心，满招损，谦获益，犹朝必有暮，冬必有春。乾上自剥居谦之三，曰「下济而光明」，光明艮体。坤三自剥居谦之上，曰「上行」。阳止于外而在坤上，为「剥」。阳止于内而在坤下，为「谦」。观一阳升降，天地人鬼之情状毕见矣。圣人立象系辞，于「谦」尤拳拳，盖使天下后世俯仰动作之闲，不敢须臾忘谦，而思所以善其后也。「谦尊而光，卑而不可逾」，君子之终也。君子德盛礼恭，以充尽谦道，故处上而人乐推之，居下而天下后世视为楷式，周公、孔子为然。周公令德久而不替，有终也。然则圣人何为而臻此？其必曰「性止而德极于盛，体顺而礼极于恭」故欤！九三以阳处艮上，为尊、为光；位在坤下，为卑、为不可逾。周、孔一道，用之尊则光，用之卑则不可逾，惟所用也。</p><p>象曰：地中有山，「谦」。君子以裒多益寡，称物平施。</p><p>摧其高刚，而心止乎顺，然后能行礼于身，以尽夫谦。礼行于身，斯可以行于天下矣。夫顺天地鬼神之道，使天下远害而就利，必有礼制存其闲。「艮」有止限义，而「坤」道主平，若井田行而王道盛，无他，圣人用谦于身，又率天下而纳之谦，大功以立，大治以成，谦用大哉！昔先王制礼，使贤可俯而就，不肖可跂而及，贵者不至骄，贱者不至污，无有余，无不及，用此道也。杂卦曰：「谦以制礼。」地中有山，山得其平，斯盖制礼之象。</p><p>初六，谦谦君子，用涉大川，吉。象曰：「谦谦君子」，卑以自牧也。其身谦，其心谦，内外俱进，非静养之功，何以至此？且人不能尽力于谦，本夫放心。不知求放心，则骄亢怠傲，将一肆心之所为，其能行己以恭，而有所建立于天下乎？君子止心至静，不挠不夺，其积功非一日，欲忿毕除，诚信益大，故德止于内而盛，礼顺于外而恭。谦之又谦，可以得天下心而济其难。「卑以自牧」，盖君子止心之道。必曰「卑」云者，逊志之学。惟逊志不矜伐，用能自牧。「谦谦」之德，本夫自牧。初以柔处艮下，体又承坤，为「谦谦」。互坎，为「涉大川」。上坤下艮，坤为马，为牛。坤为地，艮为山，为自牧。</p><p>六二，鸣谦，贞吉。象曰：「鸣谦贞吉」，中心得也。</p><p>二以柔德居艮止中，德积于中，谦形于言，其所以感动上心，莫非至诚忠厚，有益国家之论，非谀说无益之辞。曰「鸣谦，贞吉」，二何以贞？惟中心自得，不畔于道，是以贞。贞则得君，而道行天下，是以吉。互坎，坎水，为「鸣谦」。坎阳在中，为中心。九三，</p><p>劳谦，君子有终，吉。象曰：「劳谦君子」，万民服也。有大功而不自以为功，若禹不矜伐，周公、公孙硕肤二圣人者，皆获有终之吉。三自师来，曰「劳谦」。夫勤劳王家，臣之常分也。矜伐之心一生，则恃功忽下，安宠擅事，天下之争所归，非所以自全也，其能保有万世令名，而服天下之心乎？以刚阳居群阴中，为君子。艮终始为有终。坤众在上，已下之为万民服。</p><p>六四，无不利，㧑谦。象曰：「无不利，㧑谦」，不违则也。谦至四，德成矣。上承谦恭不伐之君，下履功德盛大之臣，㧑其谦而散之，不陵上，不渎下，动皆中理，臣道斯盛。艮下互体又艮，艮手为「㧑谦」。不违则谓何「㧑谦」？疑有失中之举，惟德成而动容周旋中礼，故不违则。四以六居位，得坤道正，且德顺有常，㧑谦孰利？互坎，坎，法律为则。呜呼！若四岂徒能保守其爵位而已，其敦厚有容之德，殆将使天下后世一视以为法，而安靖国家之福，何可量哉！六五，不富以其邻，利用侵伐，无不利。象曰：「利用侵伐」，征不服也。</p><p>履天下大位，而不自满假，以亲比上下，上下一心，不服可征。五柔中，得顺止正，且刚中，群阴莫不协辅，「谦」德为大。然则五犹有侵伐，何也？盖奸宄害治，治世所不能无，惟「谦」德之大，天下属心，用能正天下之不谦，以成其治。舜命禹征有苗，舞干羽格之，初不待兵刃之接，无不利也。互「坎」在中，「坎」阴为不服，为侵伐。夫圣人用「谦」，盖将以收天下心，而除其为天下害，非徒徇谦德虚名，而优游玩日，不恤生民之罹毒也。君人而欲得志天下，莫若反身而求其「谦」。惟「谦」则不自满假，而谓莫我若，必钦必畏，必恭必俭，必亲贤，必听言，惠泽及人者大，上下顺服，欢若四邻，用于侵伐，何往不利？群阴为「邻」，「坤」地生养万物为富。</p><p>上六：鸣谦，利用行师，征邑国。象曰：「鸣谦」，志未得也。可「用行师」，「征邑国」也。二「鸣谦」，应五也。上六「鸣谦」，将以率天下而纳之「谦」。五曰「利用侵伐」，上曰「利用行师」，「利用」云者，于用为利，未必用也。征者，正也。以我之谦正彼不谦。圣人必欲大其谦于天下，先自内始。曰「征邑国」，文王事也。文王居岐，谦德著闻。伐崇，崇违之，退修德教而崇降，其「征邑国」之谓乎？「志未得」云者，天下未由于谦，圣人所忧也。「坤」为牛，为马，曰「鸣谦」。坤为众，曰「邑国」。邑，内也。上六正应在三，三以刚阳居互坎中，有负恃怀险心，为志未得。䷏ 坤下震上 豫，利建侯行师。</p><p>彖曰：「豫」，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况「建侯行师」乎？天地以顺动，故日月不过而四时不忒。圣人以顺动，则刑罚清而民服。豫之时义大矣哉！阳德内升，顺道而动。其动也，因天下百姓之心，天下悦之，建侯以共治，行师以除害，安往不利？曰「利」云者，有是象不必有是事。盖阳动于地，群阴协应，天地中和之气达矣，是为「豫」。豫惟顺动，故治可兴，害可去，而豫治益大。坤，震位。上下为侯。四自师来，为「行师」。「刚应而志行」，谓四也。九四以刚获群阴应，而其道上行，曰「刚应志行」。云「顺以动」，豫九四致豫之道。豫，顺以动，故天地如之，而况「建侯行师」乎？言豫之顺动，上可与天地合其德。「建侯行师」之利，盖理之必然，无可疑者。天地以顺动，故日月不过而四时不忒。圣人以顺动，则刑罚清而民服。豫之时义大矣哉！申言圣人合德于天地者如此。夫天地之动无心，而行以中气，未至不先之，至不后之，是以日月四时得其正。圣人法天地，因人心之中而用吾之中，以有为于天下，道无不顺，刑罚可省，民心说服。曰「刑罚清而民服」。刑罚不清，则中和之德不能纯被于上下，民之从之，革面而已。故「豫」以刑罚清为大。雷动于上，「坤」顺于下，为天地以顺动。「震」，春阳用事，时以序行，为四时不忒；互坎在中，为日月不过；「坎」水为刑罚清；「坤」下坤众，为民服。且阳乾自剥来，一曰「复」，复心之刚，以复其德也。二曰「师」，德复而后可以去天下害也。三曰「谦」，圣人德大功立，不自矜伐，以来天下之善也。四曰「豫」，阳气奋达，利物之功益著，乐所由作也。五曰「比」，天下顺「比」，王道至是而盛也。六曰「剥」，守中则「比」，过则剥。「剥」，圣人之戒也。中其至乎？君用之仁也。尝考一阳之生，自复至「比」，皆有兵戎象。「复」</p><p>上六曰：「迷复凶，有灾眚，用行师，终有大败。」「师」九二曰：「在师中吉。」六五曰：「田有禽，利执言。」「谦」六五曰：「利用侵伐。」上六曰：「利用行师。」「豫」曰：「利建侯行师。」「比」九五曰：「王用三驱，失前禽。」盖阳动而复，天威已行，至「比」则威德益著，而生物之功至大。圣人生物之功在兵，兵以德胜。圣人复其心以复其德，复其政事，然后可以行师之众正，可以举谦之征伐，可以体豫之行师，可以讲比之三驱，此一阳用事之序也。夫天下顺比而不忘三驱，礼焉。圣人仁爱天下，惟恐一朝备弛，而害加于百姓。后世天下始定，儒者急急偃兵息民之说以从事。夫礼乐之文，导君骄奢纵逸之地，卒至败人之国，岂不陋哉！若夫天下未定，而曰「我无事于复，玩岁乐身」，以兵为讳，吾不知危亡之日矣。戒之哉！</p><p>象曰：雷出地奋，「豫」，先王以作乐崇德，殷荐之上帝，以配祖考。</p><p>先王躬行之德，洽于天下，百姓之害除，而天下大悦乐，于是可作。乐由阳来，乐作而德益崇。夫使天下率由礼乐之化，是先王有以生之。先王圣德日加于天下后世，不知何时而已，故曰「作乐崇德」云。「荐上帝」，归功于天也；「配祖考」，归德于祖考也。「帝出乎震」，「震」在卦上为帝，二阴在震上为祖考。上帝曰「荐」，荐以尽诚；祖考曰「配」，配以合德。</p><p>初六：鸣豫，凶。象曰：「初六鸣豫」，志穷凶也。</p><p>谀说之志萌于中，发于声音颜色。盖小人阴柔至甚而无持操者，是岂惟安逸豫以害其身？推是心以往，且将害家、害国、害天下，故「凶」。初以柔处坤下，其志委靡不振，以己不正，资幸四应，惟谀说之图，而四有刚德不己合，是以志穷而凶。夫初本震体，用震变坤，失其刚矣。刚德一失，邪枉若是，吁，可畏哉！震动为鸣，圣人于「豫」，首发「鸣豫」戒。盖方天下安乐无事，谄佞者易进，圣人致戒于初，不惟使小人知所惩艾，欲天下后世之为君臣者，深察而钦远之也。</p><p>六二：介于石，不终日，贞吉。象曰：「不终日，贞吉」，以中正也。静故能照。夫当天下说豫时，谄渎以交上下，不比于权，即昵于谄，驯至丧身亡家乱国无疑矣，岂为先见者哉？二有静止至德，道之光明足以见几于先，曰：「介于石，不终日，贞吉。」或曰：二履人臣正位而介于石，若安静无补于豫者，得无过乎？是不然。夫天下说豫，人各循其所说而不虞后害，古今一情也。二处坤位中，立德止静之地，而智足以见天下几，上不谄于九四，下不渎于二阴，厚德镇浮存豫，有移风易俗、守正止难之功，为用至大。夫子著上交下交之义于系辞，盖以卦之上下言之。互艮，「艮」为石。震再变有离体为日。贞吉，谓以中正获吉。豫九四有权臣象。天下说从，祸福之分，在四所处正不正闲。吁！为四亦可危也。不有中正君子若二者，孰能行礼于身，以杜绝未萌之志，而正君臣大义哉？若二阴小人谀说之雄，安可迩？迩之丧德必矣。系辞曰：「君子知微知彰，知柔知刚，万夫之望。」圣人深以二有功于「豫」，谓天下后世宜仰望以为标准也。</p><p>六三：盱豫，悔，迟有悔。象曰：「盱豫」有「悔」，位不当也。</p><p>仰而视曰「盱」。三位不中正，以阴比阳，切切然觊望之意见眉睫闲，曰「盱豫悔」。而四方为「由豫」主，迟其行又无以趋事赴功，曰「迟有悔」。然则君子处此如何？惟自反以修德而已。德苟中正，上必我求，何盱迟足云？圣人恶夫在豫求之人，不求之己殆，为容悦计者，设此象以示悔之必至也。「震」再变「离」，「离」为目，曰「盱」；在「坤」阴上，阴性缓，曰「迟」。</p><p>九四，由豫，大有得。勿疑，朋盍簪。象曰：「由豫，大有得」，志大行也。</p><p>姬旦总群臣以辅成王，诚信而已矣。惟其待天下以不疑，是以得贤才之助而永保功业。汉霍光反之，不再世而丹族。吁，可戒哉！夫疑心一萌于胸中，天下士将望望而去之，孰与辅其德、成其治乎？曰「勿疑」，言疑之不可一朝而或生于心也。众阴归之，由我而「豫」，为「由豫」为「朋」，为「大有」，得坎中为「勿疑」。一阳为首，为簪，众阴为发。夫四以阳德孚五阴，惟履位不正，圣人故有「勿疑」之戒，惧夫诚意或怠，以失天下之贤，极言诚之不可已耳。夫众贤协归，则上可安宗庙，次可安百姓，下可安吾身。疑心一生，合者将离，尚可以致天下之豫哉？夫惟尽其在我之诚，使无愧于天地，无欺于幽明，若雷动而奋仁德以行，天下之贤其将合志同心以赴事功之会，而我之德业永永无穷矣，岂不美夫！且近臣何疑哉？不过曰恐贤才之胜己而扼其进，自非有至谦之德，而以天下为心，不以一己失得为心，能勿疑乎？九四自谦来，宜其由豫而大有得志以之行也。</p><p>六五：贞疾，恒不死。象曰：「六五贞疾」，乘刚也。「恒不死」，中未亡也。</p><p>呜呼！人君惟不安于逸豫，则志气清明，其德刚健，大臣乌得以擅事于下？六五以柔履中，刚健不足，四承之曰「贞疾」。盖柔道多牵，虽曰柔中，而众柔位上下，在豫必怠，宜不能有为天下也。周室东迁则然，五犹居中位，曰「中未亡」，其以先王德泽尚存乎？互坎，「坎」，心病，为疾。「震」于稼反生，为不死。夫五以四豫，圣人有「贞疾」之训。圣人戒豫之君，必欲勉进刚德，以总揽权纲于上，不当安于豫怠，倒持太阿以授其臣，春秋尊王之义也。且豫惟四履阳位，群阴刚德不足，不能为五助。孟子所谓「一薛居州，独如宋王何」者也，是以五不免夫贞疾。呜呼！人君慎无厌夫刚德之贤而亟远之，使朝多君子，君其有不尊，德其有不修，国其有不治，虽有任事当权之臣，不能私己而擅其事矣，何贞疾之忧乎？</p><p>上六：冥豫，成有渝，无咎。象曰：「冥豫」在上，何可长也。阴极为冥，性移志昏，故冥成有渝，许变也。书曰：「惟狂克念作圣。」有渝之功也。上处震上，震动曰「有渝」云。夫冥而渝，犹庶几可保其宗庙社稷也。不渝，沦亡无日矣。人君其戒夫豫而不知反者哉！䷐ 震下兑上 随元亨、利、贞，无咎。</p><p>彖曰：「随」，刚来而下柔，动而说，「随」。大亨贞，无咎，而天下随时。随时之义大矣哉！</p><p>随，否之变，刚自乾来，下坤之柔，曰「随」。一变随，再变归妹，三变泰。随，大亨，利在贞。不贞则无以率化天下，而天下莫之从，曰「随，元、亨、利、贞，无咎」。夫刚来下柔，民心以孚，有所不动，动则说矣，是谓「随」。盖民之系命在贤，下柔则贤者获用而得民之心，用是以动天下，其有不说从而率化者哉？「大亨正无咎，而天下随时」，谓得贤而民心归，亨大以正。且夏忠、商质、周文，圣人不能违天下心，惟正，故天下乐从而莫违其教化。然则天下所随者时也，时实圣人为之，是天下之随，在圣人不在时。圣人贞动，天下说随，其义大矣。且天道之运，自春徂秋，岁功以成，天下日用而不知，随焉而已。若夫圣人以贞动，而使天下欣欣然从而化之，亦若人之随时于天也。</p><p>象曰：泽中有雷，随。君子以向晦入宴息。</p><p>潜神至静之地，而后能尽动说之道于随。庄子曰：「渊默而雷声，神动而天随，从容无为，万物炊累焉。」盖静者动之基，潜阳之德，养于至静，动以利物，其动乃说。君子向晦宴息，盖随时而养之以静也。君子存身于静，其动也仁。天下说随，大功以著。兑西方，为向晦。互巽为入，互艮为宴息，互震至兑息。伏曰「泽中有雷」。呜呼！天地以至静之德生养万物，君子以至静之德生养天下。传曰：「君子有四时，朝以听政，昼以访问，夕以修令，夜以安身。」夫安身而后动，则清明在躬，平旦之气不昧，而利物之仁大矣。此君子用随于一日之闲者然也，可不慎夫？</p><p>初九，官有渝，贞吉。出门交有功。象曰：「官有渝」，从正吉也。「出门交有功」，不失也。君子动静本道，惟道之从，事虽变渝，于道常贞，得所随矣，故「吉」。「出门交有功」，谓如是而后可有为于随也。盖吾之所随既贞，功利何为而不及天下哉？初从乾上居震下，为有渝。互艮为门。初本乾体，乾道也，贞也。自震以往，万物滋生，为有功。「交」谓应四。</p><p>六二：系小子，失丈夫。象曰：「系小子」，弗兼与也。</p><p>随道在系夫正否，且随匪其贞，在我则德损，在事功则必不能建立，在天下则必不能惠利，可不慎择欤？二柔中无失德，然于「随」用柔，柔道多牵。曰「系小子，失丈夫」，谓舍五正应系初也。且初于「随」为动说主，何以谓之「小子」？初自乾上居坤下，在卦体得「动说贞」。卦曰：「随自初发也。」若爻言其变，则初位在最下，有互艮体为小子。「系小子，失丈夫」，惑彼动说，舍吾正应，是「失随」之「贞」者也。「失贞」何以从事于「随」？圣人系六二象辞曰：「弗兼与也。」以二在随，居人臣中位，舍应与初，义有大不可者，其戒夫居陋而不诚心一意以事其君者欤！四、五以乾阳在上为夫。</p><p>六三：系丈夫，失小子。随有求得，利居贞。象曰：「系丈夫」，志舍下也。</p><p>舍初从四，四以道事五，因四以通五，志必行于随，「随有求」而得者也。「利居贞」谓何？臣事君，有君而已。惟道惟君之随，人臣大义也，其可不安而行之？三系四而曰「利居贞」者，盖圣人深著不可附丽权臣之戒。夫四事君以道，三之系四，本以通五，求而得之，贞莫大矣。「志舍下」，谓舍初。互巽，巽入为「求有得」。</p><p>九四：随有获，贞凶。有孚在道，以明，何咎？象曰：「随有获」，其义凶也。「有孚在道」，明功也。</p><p>伊尹、周公，臣也，而实受天下随，处伊周任重甚难，其道虽贞，其义则凶。惟至诚守道，动皆中理，则君信不疑，功可成矣。伊周事业卒暴白于天下后世，诚也。且己孜孜然正心钦己，日以匡国家利天下为事，譬日月在天，有目有趾，莫不待以成功，何咎复得哉？故曰：「有孚在道以明，何咎？」而象以为「明功也」。盖有孚在道，则动必中道，事业日著，是为「明功」。九四居动说相应，中有互艮体，艮手为有获，艮刚止于中为孚，为道，艮其道光明为以明。</p><p>九五，孚于嘉，吉。象曰：「孚于嘉吉」，位正中也。</p><p>中德日修，贤者信之，惠然肯来，曰「孚于嘉」。贤者随之，则天下莫不随矣。传曰：「天下之父归之，其子焉往？故吉。」「嘉」指二，二柔顺中正，在随为「嘉」。不然君臣俱刚，何以随？惟刚柔相济，而以中率天下随，随道「亨」矣。二居震中，万物自此趋亨嘉之会为「嘉」。五以兑中应二，阴阳之气各得中相应，是以「孚」也。</p><p>上六：拘系之，乃从维之。王用亨于西山。象曰：「拘系之」，上穷也。</p><p>既「拘系之」，又「维之」，人之说从，有不能自解也。固结人心本于仁。太王去邠，周业以昌，王道以行。「上穷」云者，若太王事之以皮币犬马珠玉，不得免焉也。太王其事穷，其道通。自三至上，互体皆「巽」，巽为绳，故有「拘系」「维之」之辞。上六居动说上，天下乐随，而所履阴位，以阴在上，志未行于随，曰「上穷」。䷑ 巽下艮上</p><p>「蛊」，元亨，利涉大川。先甲三日，后甲三日。</p><p>彖曰：「蛊」，刚上而柔下，巽而止，蛊。蛊「元亨」，而天下治也。「利涉大川」，往有事也。「先甲三日，后甲三日」，终则有始，天行也。天下事至陵迟大坏，莫可支持，自人君心念始。君心不仁，而奢侈暴虐之为，流毒天下，则邪佞得志，忠良退黜，日复一日，纲纪浸弛。蛊之为由心起也。坤柔下消乾刚，仁心沦失，泰治以堕，风化于是衰矣。必复其心，蛊乃可治。蛊以「元亨」，元仁也。「蛊，元亨，利涉大川」，将有事于天下，以正其弊，大其治也，故涉川为利。序卦曰：「有事而后可大变。」「巽」互坎在中，为「利涉」。先甲三日，后甲三日。何谓治蛊？在仁德，在挈纲领而图其本在不息。甲十日，长仁也，万事之本也。夫事之弊坏，非大振其纲领，而务以仁德洽天下，使天下归心，则事莫之兴起。「先甲三日」，要终而思其弊；「后甲三日」，图始而慎其行。终而复始，法天之健，可以致治。乾纳甲，先三日，「巽」初也；后三日，「艮」上也。治蛊者可以复泰。巽一变为小畜，乾在下；四变为无妄，乾在上。「先甲后甲」象也。「蛊」，刚上而柔下，巽而止，蛊。蛊元亨而天下治也。「利涉大川」，往有事也。「先甲三日，后甲三日」，终则有始，天行也。人君刚健，笃实辉光，日新，其德事奚蛊？惟刚上而止，柔下而顺，为君者高亢而德日消，为臣者邪佞而权日盛。臣顺而谄，君止而怠，治道以堕，蛊之所以蛊也。且夫刚上柔下，巽而动为「恒」。震巽刚柔相配，阴阳各得其位，是以有常而亨也。刚上柔下，巽而止为「蛊」。少男在上，长女承之，阴阳失其序，拂其常，譬夫柔顺之臣有以蔽惑其君，而君安之，不蛊何为哉？圣人观象治蛊，用巽之仁，复艮之静，仁德既止，天下率化，而蛊可亨。曰「蛊元亨而天下治」。曰「元亨」云者，仁而后亨，蛊以仁亨也。如是而后可以大有为于天下。巽一变乾为天行。巽木为利涉。</p><p>象曰：山下有风，蛊。君子以振民育德，</p><p>作成人材，以兴弊补坏。周宣用之。夫人各有德，顾在上者养之如何耳。先王盛时，学校兴，礼化行，终致天下之材不可胜用，振而育之之功也。且「山下有风」，失其常度，非长养万物之风也。譬诸风俗陵坏于天下，君子观象，将以复风化而大变其俗，育德其可缓哉！</p><p>初六，干父之蛊，有子，考无咎，厉终吉。象曰：「干父之蛊」，意承考也。</p><p>行巽之权，阴救其弊，而实显其美，曰「有子考无咎」。坤上来居乾下，为干父之蛊。乾初在上，父象也。夫初以巽仁居蛊下，有仁德以治蛊，而欲一大变其风俗，其意专在尊宗庙，定国家，育民人，子道既尽，考德以大，是谓「有子」，是谓「考无咎」。「厉终吉」，戒以诚勉也，厉而吉可终矣。初柔顺，非厉则德莫之进，位去上最远，曰「意承考」。</p><p>九二，干母之蛊，不可贞。象曰：「干母之蛊」，得中道也。事继世主而事适堕坏，求以治之，其道贵中，不可过，过则失中，且强所难能，卒不可行，何益于治！周公相成王，善用其中，终能大文、武之业。「不可贞」，谓不可过贞，非直谓贞道不可行也，故夫子明为之训，曰「得中道」云。二以刚居「巽」中，是谓「得中道」。九三，干父之蛊，小有悔，无大咎。象曰：「干父之蛊」，终无咎也。</p><p>为子为臣，刚中是贵，刚不可过，然在「蛊」，刚过犹愈于「裕」。三刚过中，与上敌应，事固有力争必行者，故「小有悔」。惟其设心立意本于治「蛊」，而卒归于正，是以「无大咎」。然则人君用臣于「蛊」，宁取刚过，无取裕，裕何以立事而保其社稷人民邪？</p><p>六四，裕父之蛊，往见吝。象曰：「裕父之蛊」，往未得也。「蛊」至四，「巽」极而止，故「裕」。西汉公孙弘以阿容无补君臣之闲，吝道也。夫居上位，不汲汲救天下弊，玩日偷安以幸其无事，不仁莫大。若是者，民将视之犹仇雠，谓不我恤也，何往而得志于君哉！阴止于下，有兑说体为「裕」。上本乾位，故二、四、五皆曰「干父之蛊」。</p><p>六五，干父之蛊，用誉。象曰：「干父用誉」，承以德也。</p><p>承以德，不承以事，故「用誉」。且举行政事末节孝之细，又安能有惠及天下，且有令闻于后世哉！五得柔中，其位艮止巽上，心止于仁，臣刚而应用，能修德于蛊，以来厥誉。夫天下之事，委靡弊坏，莫之振起，究其本原，在德不在事。德失则事弛，德修则事立。君人者欲显亲而大其业，以尽夫奉先宁亲之孝，莫若反己行仁，勉夫在我之德。互兑为誉。</p><p>上九，不事王侯，高尚其事。象曰：「不事王侯」，志可则也，不有其功。记曰：「终事而退，臣之厚也。」位居艮上，艮止，为「不事王侯」。伊尹复辟告归，体此也。后世若汉留侯，天下已定，奉身而退，庶几高尚者哉。不然，已在上位，无补天下国家，而曰「我姑退」，是足为高乎？上九自乾来，有刚健果断之德。且蛊至上，仁德已孚，天下已治，君子洁身而去，以顺天道可也。不然，咎将及之。「志可则」谓何？功成身退，不率宠辱，志在利天下，而不在夫享天下之利。进退有度，其志可则。变巽有离体为志。䷒ 兑下坤上</p><p>临，元亨利贞，至于八月有凶。彖曰：临，刚浸而长，说而顺，刚中而应。大亨以正，天之道也。「至于八月有凶」，消不久也。</p><p>乾阳序进，以复其位，至临而二阳生于下，刚德内充，足以有临。「元亨利贞」，乾四德也。临有复乾之道，而乾德未备，其见于用者，大亨以正而已，故彖辞别白言之。「八月有凶」，戒也。阳长而临，己戒阴生，圣人知几，自昔保天下者率兢兢。尧咨舜，舜命禹，皆曰四海困穷，天禄永终，惧有凶也。推是心以临天下，又安有失德于身者乎？自此至遁，历八数，曰八月。刚浸而长，说而顺，刚中而应。大亨以正，天之道也。圣人明临之「利贞」，本诸天也。临自坤变，乾刚上进，将复坤以归乾，天道行乎其中。「刚浸而长」，指二阳。「说而顺」，卦体。「刚中而应」，谓二。九二刚中，道德之美，上说君心，而六五下之，君臣合德，以临天下，天下顺说，其亨也。大临曰「天之道」，无妄曰「天之命」，道自下升，命自上降，盖刚德浸长，而生物之功著，道之自然也。是故天道之大在生物，生物者，天道之贞。君子协进生物之功，可以配天。易以刚长为天之道，其旨深矣。</p><p>象曰：泽上有地，「临」。君子以教思无穷，容保民无疆。二阳说于下，四阴顺于上。阳为德，阴为民。君子之德足以说民心，而民顺从之也。自古先王临天下，任德教，不任刑罚，深仁厚泽，思有以固结天下之心无已，民之从其教化也亦无已，故远而夷狄，恃之以安，所容保者大哉！后世以势临人，一决而溃，德教浅也。三复斯象，知教化防范不可一日弛于天下。兑口泽，说为教，泽为容，无穷无疆，皆自坤发之。泽上有地，临民而得其防，且得其欢心也。读礼书坊记篇，君子设教，其思为长久计也审矣。</p><p>初九：咸临，贞吉。象曰：「咸临贞吉」，志行正也。</p><p>二阳以兑说进，兑为泽，其体虚，曰「咸临」。「咸临」，盖公其志，虚其心，以道而感通乎上者也。初九位在阳先，必贞而吉。夫四阴以上临下，阴惟阳之求，初以阴居下，苟所适不正，莫可有为于临矣。惟初得阳之一，志，专应四而求比于五，以阳感阴，其诚易通。临大之治，其基于此乎！渐曰：「进以正，可以正邦。」然则在临之先，必贞，然后可以临人，而易变其风俗也。</p><p>九二，咸临，吉，无不利。象曰：「咸临吉无不利」，未顺命也。事君而感之以道，利孰大焉！道，何也？中也。二得位得时，而以刚中应五，道合从，弗合去。盖必有以感动人主心意，收大人正君之效，俾纯于乾德而后已。固不肯偷容苟合，终至危人之国，使其君不能有临也，故曰「无不利」。阳进阴伏，而君臣之德同，何往不利？大抵致其君为尧舜君，必有所以大正其心，固非屑屑顺命者能之。「巽」为命，反巽曰「未顺命」。且阳进变阴，志方上达，彼岂肯以顺而丧其节也哉！</p><p>六三，甘临，无攸利。既忧之，无咎。象曰：「甘临」，位不当也。「既忧之」，咎不长也。</p><p>三居兑说上，其位不中，以柔顺之资求说二阳，是谓甘临君子。说之不以道，不说也。如之何欲以甘临君子哉？夫临人而不能内尽其诚，徒规规求说于外，若百姓固可欺，斯须而其久必离，何哉？诚不足以固结其心也。况用之君子，安能有说，而觊幸君子肯从己欤？在临，「无攸利」矣。六三互位有坤顺震动、艮止象，动而能止为既忧，忧之如何？易心退听，而以至诚顺君子，斯可也。下君子而化之，阴消阳复，驯可致泰，于临何咎？且夫甘，德之失也。德失忧之，可以无咎。吾以是知迁善功足以格天，独患夫为之不力耳。</p><p>六四：至临，无咎。象曰：「至临无咎」，位当也。</p><p>五曰「大君」，四曰「至临」。「至」，坤德也。四以顺德下应初阳，临下顺贤，其德必进，其道必行，临之至也。夫四位近君，互体坤中，而一心应阳，不挠其进，上顺于君，下说于民，臣德至矣，何所可咎？象言「位当」，谓与初正应，其位当也。</p><p>六五：知临，大君之宜，吉。象曰：「大君之宜」，行中之谓也。内有刚德，而用之以柔，「知临」也。且夫人君惟不知行中，而亢志自用，疏远忠贤，是以在治忘乱，不戒阴生，政事法度，浸至堕坏，而失夫所以临莅之道。临二阳浸长，君子道盛，君天下者，于此何为哉？行中德以任君子，斯无为而利泽及天下，得临之正矣。盖人君据大位以临天下，每患恃其聪明智力，而不知屈己下贤，骄盈怠傲，日肆一日，忠言莫告，以颠以覆。若是，则君不君矣，非所宜于临也。六五用柔之中，德顺有常，虚其心，损其刚，下应于阳，凛凛然惟惧阴之复生，而尽诚以行其中，二阳协应，临道以大，吉，孰御也？周成任周公为知临，政事一出，恃为心腹。周公聪明智力，成王之聪明智力也，成王知临矣。刚长于内，将复于乾，且得贤而所临者大，曰「大君」。六五居坤顺中，下履兑泽之虚，德顺有常，而能虚己下贤，是以有「大君」之称云。</p><p>上六：敦临，吉，无咎。象曰：「敦临」之吉，志在内也。上处临极，反得坤之厚，不以势位临下，操心积意，惟贤之顺。二阳非己应，拳拳若不一日忘，德之厚也，曰敦临。且居上临下，而独以厚贤为志，贤进道泰，天下说归，吉可得矣。坤上为敦，兑承坤，以兑阴合坤阴，复有坤体下临二阳，为志在内。夫临人而在上位，鲜不骄亢自处，蔑弃贤才。非厚德君子，以天下百姓为心，未有能善用其志者矣。䷓ 坤下巽上 观盥而不荐，有孚颙若。</p><p>彖曰：大观在上，顺而巽，中正以观天下。</p><p>「观盥而不荐，有孚颙若」，下观而化也。观天之神道，而四时不忒。圣人以神道设教，而天下服矣。</p><p>阴生一曰姤，二曰遁，三曰否，五曰剥。阴长阳消，其卦多凶。四阴乃有观象，圣人意何在也？圣人忧阴之起，思有以止而化之，为君天下计甚厚也。夫使为天下君，而能本中正至刚之德以莅天下，天下观而化之，可常治无乱，又何忧阴之复起哉？且观自临来，二刚之德浸长于内，至观刚得位而在上，执巽之仁以孚率天下，悦服归之，化道于是盛行焉。稽诸天道，观为八月卦，兑金用事，化万物而揫敛之，将使复其纯一之性，非若否之闭而不通，此观之所以独异于诸卦也。</p><p>观，盥而不荐，有孚颙若，谓何？祭祀之礼，先盥后荐。始盥则诚至，荐怠矣。人之通情也，盥而不荐，则诚德不息，始终如一，足以感格其孚颙若，下观而化，观道于是盛矣。舜恭己正南面，颙若也。盖圣人之诚，本自修身，而中正者，修身之本。圣人体中用正，无过失于天下，举海内之心皆为我心。心之所格，孰不化？「颙若」之用，斯为大。九五以巽仁居互艮上，艮止为有孚，互巽洁齐，艮手为盥。下坤，坤地备物为荐，坤在内为不荐。「大观在上，顺而巽，中正以观天下」，谓何？圣人于天下，一视同之，其德大，曰「大观」。阳大在上，曰「大观在上」。顺巽所以行其化，中正所以成其化。顺巽中正，孰不心悦而从之？下观而化，理宜然也。观天之神道，而四时不忒，圣人以神道设教，而天下服矣。神者何？诚也。天以诚运，而四时不失其序。曰「天之神道」，圣人仰观诸天，以躬行其至诚，有教存乎其间。本之仁义，著之礼乐，施之刑政，皆教也。圣人之教，自身达之天下，斯民从化，莫知所从，其道如神，曰「圣人以神道设教」。诗云：「自西自东，自南自北，无思不服。」神道格应之功也。四阴有四时数，巽风为神，坤顺为天下服。象曰：风行地上，「观」；先王以省方观民设教。</p><p>教之本在诚，其具则礼乐刑政。夫礼乐刑政必因其俗，若风行地中，随所寓以致生养之功。夫先王之省方，以至诚爱民之心而修其教化，不徒出也。巽白眼为省方，为观，申命为教。坤地为方众为民。</p><p>初六，童观，小人无咎，君子吝。象曰：「初六童观」，小人道也。初以阴处坤下为童，智不足以有观，若童之无知，曰「童观」。语曰：「民可使由之，不可使知之。」谓民可率而使由吾化，不可强以知也。童观在小人则无咎，若夫士君子不能观上德化以修其身，而朝夕于中正之归，何补天下？是君子无所用于观也，其道吝。「观」自乾变坤，故初有君子、小人二象。</p><p>六二，𬮭观，利女贞。象曰：「𬮭观女贞」，亦可丑也。</p><p>阖户谓之坤，居坤阴中曰𬮭。乾一变巽，卦体互巽，巽白眼为𬮭。阴得中为「利女贞」。互巽兑有顺说之性，为丑。且夫履柔守静，臣道之常。然大观在上，非刚中之臣则不能与上合德，以格正其君，而大有为于当世。故君子必谨养刚德，俾识明学正，而后有远大之见，可副大观之求也。且处群阴中，而厥观不远，昧于大体，上有刚健中正，君以至诚之意风动天下而己，默默守常，无所建明，顺说以从其上而已。君子不知耻可也。君子而知耻，能一日安于观哉？曰「利女贞」，女以是为贞，其事则可丑也。夫女从人者也，若君子道合而后从，其所见远且大，又安肯枉己狥人，若𬮭观者所为乎？</p><p>六三，观我生，进退。象曰：「观我生进退」，未失道也。</p><p>度己德业以为进退，曰「观我生」。君子事业以生物为本，读生民尊祖之诗可见矣。六三位虽不中，而得「坤」正体，顺静有常，进退之际，知所钦择。虽然，三在观已近高位，于是而始图进退，可乎？盖三度己德不若四，推四而下之，不敢率先以上比大观主，于臣道未失也。变「巽」为「进退」，「坤」地为「生」。呜呼！后世不度德量才，以贪冒大位，蔽贤疾能，莫知省己，以贻祸天下，观六三之风，亦可少愧矣。彼岂知一己进退，天下休戚利害系之，安可重一己而轻天下哉！是大惑大愚者所为，君子不取也。</p><p>六四，观国之光，利用宾于王。象曰：「观国之光」，尚宾也。书称尧曰「光被四表」，舜曰「重华协于帝」。人君光明之德，本于性，成于学，著于天下。君有明德，动作施为，罔不率由礼义，天下将化之而为礼义，国其光矣。四体仁巽之实，群阴毕顺，盖贤德之大者，用能观国以观君，观君以行志。王如宾之弗臣，则道德日闻，功效日著，利莫大矣。且大观在上，必有不召之臣相与躬行中正于上，化道斯盛。「巽」东南宾位，故曰「利用宾」。孔子释四曰「尚宾」，谓道德之臣宜尊显其礼而师友之，不可轻也。二阳得位，在坤上，为国光。</p><p>九五，观我生，君子无咎。象曰：「观我生」，观民也。</p><p>君臣事业在生物，而人主生物之德尤著见于民。盖君正则民正，君民一体耳。譬犹响之应声，影之随形，德修于身，民化于远，而天下莫不安其生，遂其性，其理自然也。九五刚中在位，至诚之德既已先天下而化之，复视民从化于我何如，以反求诸身。九五化民之心诚矣，故无咎。夫民犹水也，水能载舟，亦能覆舟。君子设法至公，战战栗栗，若朽索之御六马，无斯须之念不在民，是以能常保其治也。「大观」，四阴在下，九五刚中，复有君子助，而象止「无咎」。盖阴势已盛，须至诚之道不息，治抵于「泰」，而后吉耳。五巽体，互艮仁以止，故于观能尽其诚，而为大观主。</p><p>上九，观其生，君子无咎。象曰：「观其生」，志未平也。</p><p>志不忘君，且不忘天下，曰「观其生」。二爻阳居之，皆曰君子。且夫四阴浸长，上九虽不当位，而道德足以为天下观，使遂漠然无意于时，将孰与助五而止阴之消？又况阴道日进，为天下害，君子于此其能自免于戾邪？「志未平」，见君子忧君忧时，心不少忘也。「五观我生」，「上观其生」，皆取坤阴生物为义。紫岩易传卷二，</p>',134)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
